plugin code
JavaScript:
/*:
 * @target MV MZ
 * @plugindesc Extends Galv_StationaryTurn - apply only while button is held.
 * @author Caethyril
 * @url https://forums.rpgmakerweb.com/threads/181094/
 * @base Galv_StationaryTurn
 * @orderAfter Galv_StationaryTurn
 * @help Free to use and/or modify for any project, no credit required.
 * Load this plugin after Galv_StationaryTurn.
 */
;void (function() {
"use strict";

  if (!(Imported && Imported.Galv_StationaryTurn))
    throw new Error("This plugin must be loaded after Galv_StationaryTurn!");

  const BUTTON = "control";  // hold to enable Galv_StationaryTurn

  const alias = Game_Player.prototype.moveStraight;
  Game_Player.prototype.moveStraight = function() {
    const v = Galv.STURN.delay;
    if (!Input.isPressed(BUTTON))
      Galv.STURN.delay = 0;        // delay is zero if button not held
    alias.apply(this, arguments);  // process as usual
    Galv.STURN.delay = v;          // reinstate proper delay value
  };

})();

